def lab_for(model):
    m = model.lower()
    if 'gpt' in m or 'o3' in m or 'realtime' in m:
        return 'OpenAI'
    if 'gemini' in m:
        return 'Google'
    if 'claude' in m or 'opus' in m or 'sonnet' in m:
