    if 'muse spark' in m:
        return 'Muse Spark'
    if model in ('—', ''):
        return 'Unknown'
    return 'Other'

def esc(s): return html.escape(str(s))

def bar_row(label, model, score, maxv=100, ci=None, rank=None):
    lab = lab_for(model)
    width = max(2, float(score)/maxv*100)
    rank_html = f'<span class="rank">#{rank}</span>' if rank else ''
    ci_html = f'<span class="ci">±{ci}</span>' if ci else ''
    return f'''<div class="bar-row">
        <div class="bar-label">{rank_html}<span>{esc(label)}</span><small>{esc(model)}</small></div>
        <div class="bar-track"><div class="bar-fill" style="width:{width:.2f}%; background:{LABS[lab]}"></div></div>
        <div class="bar-score">{score:.2f}{ci_html}</div>
    </div>'''

def mini_bar(score, maxv=100):
    width = max(2, float(score)/maxv*100)
    return f'<span class="mini-track"><span class="mini-fill" style="width:{width:.2f}%"></span></span>'

